package com.youngone.mediacontrol.identity.integration;
import org.junit.jupiter.api.Test;import java.nio.charset.StandardCharsets;import static org.assertj.core.api.Assertions.assertThat;
class CsvIdentityParserTest{@Test void parsesQuotedUtf8AndGroups(){String csv="\uFEFFexternalObjectId,immutablePersonKey,employmentStatus,displayName,groups\r\nobj-1,person-1,ACTIVE,\"Kim, One\",dev;finance\r\n";var result=new CsvIdentityParser().parse(csv.getBytes(StandardCharsets.UTF_8));assertThat(result.errors()).isEmpty();assertThat(result.identities()).hasSize(1);assertThat(result.identities().getFirst().displayName()).isEqualTo("Kim, One");assertThat(result.identities().getFirst().groupExternalIds()).containsExactlyInAnyOrder("dev","finance");}@Test void duplicateExternalIdIsRejected(){String csv="externalObjectId,immutablePersonKey,employmentStatus\na,p1,ACTIVE\na,p2,ACTIVE\n";var result=new CsvIdentityParser().parse(csv.getBytes(StandardCharsets.UTF_8));assertThat(result.errors()).anyMatch(x->x.contains("duplicate externalObjectId"));}}